    '    float col = length(rp.xz) - 0.145 + flute;',
    '    float dome = -(length(q - vec3(0.0, 0.35, 1.35)) - 2.45);',
    '    float coffer = 0.018 * cos(q.x * 14.0) * cos(q.z * 14.0);',
