    "void main(){",
    "  vec2 p = (gl_FragCoord.xy - 0.5 * R) / R.y;",
    "  float A = R.x / R.y, t = T;",
    "  float impact = exp(-max(0.0, t - 1.700) * 14.0) * step(1.700, t);",
    "  vec2 shake = vec2(sin(t * 92.0), cos(t * 118.0)) * impact * 0.0075;",
    "  p += shake;",
