    var ext = (function () { try { return new Audio().canPlayType('audio/webm; codecs="opus"') ? ".webm" : ".m4a"; } catch (e) { return ".m4a"; } })();
    (window.titanAudioFetch || window.fetch)("audio/" + (dir || "ambience") + "/" + name + ext).then(function (r) { return r && r.ok ? r.arrayBuffer() : null; }).then(function (ab) {
      if (!ab) return;
