    var x = A.ctx, src = x.createBufferSource(), g = x.createGain(), t = A.t0 + s, end = t + seg[1] / rate;
    src.buffer = b; src.playbackRate.value = rate;
    g.gain.setValueAtTime(v, t); g.gain.setValueAtTime(v, Math.max(t, end - rel)); g.gain.linearRampToValueAtTime(0, end);
    var last = g;
    if (lp) { var f = x.createBiquadFilter(); f.type = "lowpass"; f.frequency.value = lp; g.connect(f); last = f; }
    src.connect(g); last.connect(A.out); src.start(t, seg[0], seg[1]); A.nodes.push(src);
    return true;
  }

  function lay(W, H) {
    var A = W / H, port = A < 1;
    var w = port ? A * 0.80 : Math.min(0.84, A * 0.46);
    return port ? { hs: [w / 2, w * 0.375], cy: 0.04, u1: [0.06, 0.32, 0.08, 1.0] }
                : { hs: [w / 2, w * 0.375], cy: 0.01, u1: [0.14, 0.10, 0.04, 0.0] };
  }

  I.reg("bauhaus", {
    dur: 4.8, still: 4.5,
    init: function (C) {
      C.L = I.gl(C, FRAG, { scale: 1 });
      if (C.L) C.L.tex(cardTex());
    },
    draw: function (C, t) {
      var g = C.g, W = C.W, H = C.H, Ly = lay(W, H);
      g.clearRect(0, 0, W, H);
      if (C.L && C.L.draw(t, [Ly.hs[0], Ly.hs[1], 1.0, Ly.cy], Ly.u1)) return;
      g.fillStyle = "#161412"; g.fillRect(0, 0, W, H);
      var sw = Ly.hs[0] * 2 * H, sh = Ly.hs[1] * 2 * H, sx = (W - sw) / 2, sy = H / 2 - Ly.cy * H - sh / 2;
      var rev = K.seg(t, 1.1, 2.5);
      var grd = g.createRadialGradient(W / 2, H / 2, 10, W / 2, H / 2, Math.max(W, H) * 0.65);
      grd.addColorStop(0, "#e63928"); grd.addColorStop(1, "#161412");
      g.globalAlpha = 0.32 + 0.48 * rev; g.fillStyle = grd; g.fillRect(0, 0, W, H);
      g.globalAlpha = rev; g.strokeStyle = "#e63928"; g.lineWidth = 1.8;
      g.beginPath(); g.moveTo(sx + sw * 0.15, sy + sh * 0.28); g.lineTo(sx + sw * 0.85, sy + sh * 0.28);
      g.moveTo(sx + sw * 0.15, sy + sh * 0.72); g.lineTo(sx + sw * 0.85, sy + sh * 0.72); g.stroke();
      g.fillStyle = "#f4efe4"; g.textAlign = "center"; g.textBaseline = "middle";
      g.font = "italic " + Math.round(sh * 0.065) + "px Georgia, serif";
      g.fillText("weimar constructivist exhibition", W / 2, sy + sh * 0.21);
      g.font = "700 " + Math.round(sh * 0.20) + "px Georgia, serif";
      g.fillText("TITAN", W / 2, sy + sh * 0.43);
      g.font = "600 " + Math.round(sh * 0.12) + "px Georgia, serif";
      g.fillText("RELIQUARY", W / 2, sy + sh * 0.59);
      g.font = "italic " + Math.round(sh * 0.065) + "px Georgia, serif";
      g.fillText("constructivist form & weimar silver", W / 2, sy + sh * 0.79);
      g.globalAlpha = 1;
    },
    sound: function (C) {
      var A = I.audio(C); if (!A) return null;
      warm(A.ctx, "study"); warm(A.ctx, "clock"); warm(A.ctx, "organ", "cuts");
      cut(A, "study", 0.0, [0.5, 4.4], 1.0, 0.22, 0.8, 1600);
      if (A.noise) {
        A.noise(0.08, 2.2, 0.035, 380, 120, 0.8);
        A.noise(1.70, 0.32, 0.085, 820, 180, 2.2);
      }
      if (A.tone) {
        A.tone(1.70, 0.45, 92, 48, 0.06, "triangle");
      }

      return A.stop;
    }

  });
})();

