    "}"
  ].join("\n");

  function cardTex() {
    var W = 1024, H = 768, c = K.mk(W, H), g = c.getContext("2d");
    g.fillStyle = "rgb(0, 0, 0)";
    g.fillRect(0, 0, W, H);

    var fontMain = "700 130px \"Palatino Linotype\", \"Book Antiqua\", Georgia, serif";
    var fontSub  = "600 76px \"Palatino Linotype\", \"Book Antiqua\", Georgia, serif";
    var fontCap  = "italic 500 38px Georgia, serif";
    g.textAlign = "center"; g.textBaseline = "middle";
    var cx = W / 2;

    function drawContent(col, blur) {
      g.save();
      if (blur > 0) { g.shadowColor = col; g.shadowBlur = blur; }
      g.fillStyle = col; g.strokeStyle = col; g.lineWidth = blur > 0 ? 3.4 : 2.0;
      [252, 530].forEach(function (ry) {
        g.beginPath();
        g.moveTo(cx - 290, ry); g.lineTo(cx - 22, ry);
        g.moveTo(cx + 22, ry); g.lineTo(cx + 290, ry);
        g.moveTo(cx, ry - 8); g.lineTo(cx + 11, ry); g.moveTo(cx, ry + 8); g.lineTo(cx - 11, ry); g.closePath();
        g.stroke();
      });
      g.font = fontCap;
      g.fillText("sierra madre timberline camp", cx, 204);
      g.font = fontMain;
      g.fillText("TITAN", cx, 348);
      g.font = fontSub;
      g.fillText("RELIQUARY", cx, 464);
      g.font = fontCap;
      g.fillText("saddlebag hoard & spanish pillar dollars", cx, 580);
      g.restore();
    }

    // Pass 1: Red channel blurred bevel slope for 5-tap Sobel 3D surface normals
    drawContent("rgb(255, 0, 0)", 18);
    // Pass 2: Green + Red razor-sharp unblurred letter & filigree core
    g.globalCompositeOperation = "lighter";
    drawContent("rgb(255, 255, 0)", 0);
    g.globalCompositeOperation = "source-over";
    return c;
  }

  var BUF = {}, LOADING = {};
  function warm(ctx, name, dir) {
    if (BUF[name] || LOADING[name] || !window.fetch) return;
    LOADING[name] = 1;
    var ext = (function () { try { return new Audio().canPlayType('audio/webm; codecs="opus"') ? ".webm" : ".m4a"; } catch (e) { return ".m4a"; } })();
    (window.titanAudioFetch || window.fetch)("audio/" + (dir || "ambience") + "/" + name + ext).then(function (r) { return r && r.ok ? r.arrayBuffer() : null; }).then(function (ab) {
      if (!ab) return;
      return new Promise(function (res, rej) { ctx.decodeAudioData(ab, res, rej); });
    }).then(function (b) { if (b) BUF[name] = b; }).catch(function () { LOADING[name] = 0; });
  }
  function cut(A, name, s, seg, rate, v, rel, lp) {
    var b = BUF[name]; if (!b) return false;
    var x = A.ctx, src = x.createBufferSource(), g = x.createGain(), t = A.t0 + s, end = t + seg[1] / rate;
    src.buffer = b; src.playbackRate.value = rate;
    g.gain.setValueAtTime(v, t); g.gain.setValueAtTime(v, Math.max(t, end - rel)); g.gain.linearRampToValueAtTime(0, end);
    var last = g;
    if (lp) { var f = x.createBiquadFilter(); f.type = "lowpass"; f.frequency.value = lp; g.connect(f); last = f; }
    src.connect(g); last.connect(A.out); src.start(t, seg[0], seg[1]); A.nodes.push(src);
    return true;
  }

  function lay(W, H) {
    var A = W / H, port = A < 1;
    var w = port ? A * 0.80 : Math.min(0.84, A * 0.46);
    return port ? { hs: [w / 2, w * 0.375], cy: 0.04, u1: [0.06, 0.32, 0.08, 1.0] }
                : { hs: [w / 2, w * 0.375], cy: 0.01, u1: [0.14, 0.10, 0.04, 0.0] };
  }

  I.reg("campfire", {
    dur: 4.8, still: 4.5,
    init: function (C) {
      C.L = I.gl(C, FRAG, { scale: 1 });
      if (C.L) C.L.tex(cardTex());
    },
    draw: function (C, t) {
      var g = C.g, W = C.W, H = C.H, Ly = lay(W, H);
      g.clearRect(0, 0, W, H);
      if (C.L && C.L.draw(t, [Ly.hs[0], Ly.hs[1], 3.0, Ly.cy], Ly.u1)) return;
      g.fillStyle = "#0c0503"; g.fillRect(0, 0, W, H);
      var sw = Ly.hs[0] * 2 * H, sh = Ly.hs[1] * 2 * H, sx = (W - sw) / 2, sy = H / 2 - Ly.cy * H - sh / 2;
      var rev = K.seg(t, 1.1, 2.5);
      var grd = g.createRadialGradient(W / 2, H / 2, 10, W / 2, H / 2, Math.max(W, H) * 0.65);
      grd.addColorStop(0, "#ff7722"); grd.addColorStop(1, "#0c0503");
      g.globalAlpha = 0.32 + 0.48 * rev; g.fillStyle = grd; g.fillRect(0, 0, W, H);
      g.globalAlpha = rev; g.strokeStyle = "#ff7722"; g.lineWidth = 1.8;
      g.beginPath(); g.moveTo(sx + sw * 0.15, sy + sh * 0.28); g.lineTo(sx + sw * 0.85, sy + sh * 0.28);
      g.moveTo(sx + sw * 0.15, sy + sh * 0.72); g.lineTo(sx + sw * 0.85, sy + sh * 0.72); g.stroke();
      g.fillStyle = "#f4efe4"; g.textAlign = "center"; g.textBaseline = "middle";
      g.font = "italic " + Math.round(sh * 0.065) + "px Georgia, serif";
      g.fillText("sierra madre timberline camp", W / 2, sy + sh * 0.21);
      g.font = "700 " + Math.round(sh * 0.20) + "px Georgia, serif";
      g.fillText("TITAN", W / 2, sy + sh * 0.43);
      g.font = "600 " + Math.round(sh * 0.12) + "px Georgia, serif";
      g.fillText("RELIQUARY", W / 2, sy + sh * 0.59);
      g.font = "italic " + Math.round(sh * 0.065) + "px Georgia, serif";
      g.fillText("saddlebag hoard & spanish pillar dollars", W / 2, sy + sh * 0.79);
      g.globalAlpha = 1;
    },
    sound: function (C) {
      var A = I.audio(C); if (!A) return null;
      warm(A.ctx, "hearth"); warm(A.ctx, "clock"); warm(A.ctx, "organ", "cuts");
      cut(A, "hearth", 0.0, [0.5, 4.4], 1.0, 0.22, 0.8, 1600);
      if (A.noise) {
        A.noise(0.08, 2.2, 0.035, 380, 120, 0.8);
        A.noise(1.70, 0.32, 0.085, 820, 180, 2.2);
      }
      if (A.tone) {
        A.tone(1.70, 0.45, 92, 48, 0.06, "triangle");
      }

      return A.stop;
    }

  });
})();

