    '    float nW = fbm3(uv * 5.0) * 0.18;',
    '    float rU = abs(uv.x - 0.5) * 1.4 + nW;',
    '    float front = reveal * 0.95;',
    '    waveMask = smoothstep(front + 0.12, front - 0.08, rU) * step(0.01, reveal);',
