        g.moveTo(cx + 22, ry); g.lineTo(cx + 290, ry);
        g.moveTo(cx, ry - 8); g.lineTo(cx + 11, ry); g.moveTo(cx, ry + 8); g.lineTo(cx - 11, ry); g.closePath();
        g.stroke();
      });
