    '  // Metallic gold vein in the marbling bath',
    '  float goldVein = smoothstep(0.025, 0.0, abs(v2 - 0.52));',
    '  vec3 goldSpec = ggx(normalize(vec3((v1-0.5)*0.4, (v2-0.5)*0.4, 0.95)), vec3(0,0,1), keyL, 0.15, vec3(0.96, 0.80, 0.36), vec3(0.06));',
