    '',
    '  // 3D Pisanello Renaissance Bronze Portrait Medal',
    '',

    '  // Volumetric Sanctuary Zenith Light Cone & Depth-of-Field Atmospheric Bokeh',
    '  float zenCone = exp(-pow((p.x - p.y * keyL.x * 0.55) * 2.6, 2.0)) * smoothstep(0.15, 1.65, t);',
