    '  col += vec3(0.95, 0.82, 0.52) * zenCone * (0.06 + 0.16 * zenHaze) * smoothstep(-0.45, 0.55, p.y);',
    '  for(int m=0; m<12; m++){',
    '    float fm = float(m);',
    '    vec2 mp = vec2(sin(fm * 4.1 + t * 0.45) * 0.48 * max(A, 0.8), mod(-0.48 + fm * 0.13 + t * (0.09 + 0.04*h1(fm)), 0.96) - 0.48);',
