      g.save();
      if (blur > 0) { g.shadowColor = col; g.shadowBlur = blur; }
      g.fillStyle = col; g.strokeStyle = col; g.lineWidth = blur > 0 ? 3.4 : 2.0;
      [252, 530].forEach(function (ry) {
