      if (A.noise) {
        A.noise(0.08, 2.2, 0.035, 380, 120, 0.8);
        A.noise(1.80, 0.32, 0.085, 820, 180, 2.2);
      }
      if (A.tone) {
        A.tone(1.80, 0.45, 92, 48, 0.06, "triangle");
      }

      return A.stop;
    }

  });
})();

