    '  float sweepPos = mix(-0.85, 0.85, clamp((T - 1.55) / 1.95, 0.0, 1.0));',
    '  float sweep = exp(-pow((uv.x - 0.5 - sweepPos * 0.65 + (uv.y - 0.5)*0.22) * 7.5, 2.0)) * smoothstep(1.35, 1.95, T);',
